0:07–0:09 — The plating
Extreme macro close-ups in rapid succession — sauce pouring in a perfect swirl, vegetables placing themselves on a plate in elegant arrangement, garnish floating down gently, a perfect steak searing in a pan with orange flames, pasta twirling through the air, parmesan grating itself in slow motion. Every shot is hyper-detailed, restaurant-quality food styling. Warm', null, null, 'missing', 5, 'keep', 'pass', 'direct', 'stylized-real', 'warm-amber', 'high-fps-slowmo', 'none', null, 'offline real-world gate: real-world: commercial, venue, kitchen, fashion', 'seedance_2.0', '@Just_sharon7', 'https://x.com/Just_sharon7', null, null)
on conflict (clip_id) do nothing;

insert into shots (
  shot_id, clip_id, shot_index, tc_in, tc_out, duration_s,
  verbatim_text, description, subject_role, action, food_item, food_role,
  setting, mood
)
select v.shot_id::text, v.clip_id::text, v.shot_index::int,
       v.tc_in::numeric, v.tc_out::numeric, v.duration_s::numeric,
       coalesce(v.verbatim_literal::text,
                substr(c.verbatim_prompt, v.slice_at::int, v.slice_len::int)),
       v.description::text, v.subject_role::text, v.action::text,
       v.food_item::text, v.food_role::text, v.setting::text, v.mood::text
from (values
